"""Hand-authored release 0.11 content; run once against 0.10. YAML is authoritative."""
import json,re,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
cat=json.loads((ROOT/'content/catalog.yaml').read_text())
existing={m['id']:m for m in cat['courses'][-1]['modules']}
all_new=[]
def start(key,title,obj,urls,extend=False):
 global meta,tasks,cards
 meta=(key,title,obj,urls,extend);tasks=[];cards=[]
def base(title,prompt,explain,hint):
 key,title_m,obj,urls,ext=meta;n=len(tasks)+1
 tid=f'encor.{key}.'+('ext.' if ext else '')+f'{n:02}'
 d=([2,3,3] if ext else [1,2,3])[(n-1)//6]
 common=dict(id=tid,revision=1,title=title,skills=[f'{key}.'+re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')],sources=[dict(title='Dokumentacja Cisco — '+title_m,url=u) for u in urls])
 return dict(common,blueprint_refs=[dict(exam='350-401',version='1.2',objective=obj)],difficulty=d,prompt_md=prompt,hints=[hint or explain],explanation_md=explain,card_id=tid+'.theory')
def card(t,example):
 cards.append({k:t[k] for k in ['revision','title','skills','sources']}|dict(id=t['card_id'],front_md=t['title'],back_md=t['explanation_md'],example=example));tasks.append(t)
def q(title,prompt,answer,wrong,explain,hint=''):
 t=base(title,prompt,explain,hint);n=len(tasks);pos=(n*3+n//6)%4
 opts=[]
 for w in wrong:
  text,reason=w.split('|',1);opts.append(dict(text_md=text,feedback_md=reason))
 opts.insert(pos,dict(text_md=answer,feedback_md=explain));assert len(opts)==4
 for i,o in enumerate(opts):o['id']='ABCD'[i]
 t.update(type='single_choice',options=opts,correct_option_id='ABCD'[pos]);card(t,answer)
def c(title,prompt,template,values,explain,hint=''):
 t=base(title,prompt,explain,hint);blanks=[];example=template
 for i,v in enumerate(values):
  if isinstance(v,str):a=[v];typ='command'
  else:a,typ=v
  blanks.append(dict(id=f'b{i}',label=f'Luka {i+1}',answer_type=typ,accepted=a,width=min(56,max(6,len(a[0])+2)),common_errors={}))
  example=example.replace('{{b'+str(i)+'}}',a[0])
 t.update(type='cli_fill_blank',platform='Cisco IOS / IOS XE; zgodnie z założeniami zadania',template=template,blanks=blanks);card(t,example)
def end():
 key,title,obj,urls,ext=meta;assert len(tasks)==18,(key,len(tasks))
 module=existing.get('encor.'+key) if ext else dict(id='encor.'+key,title=title,description='Od pojęć do analizy i praktycznych scenariuszy.',stages=[])
 if not ext:
  assert module['id'] not in existing
  cat['courses'][-1]['modules'].append(module)
 start_order=len(module['stages'])
 for i in range(3):
  order=start_order+i+1;sid=f'encor.{key}.stage-{order}';path=f'content/encor/{key}/stage-{order}.yaml'
  p=ROOT/path;assert not p.exists(),path;p.parent.mkdir(parents=True,exist_ok=True)
  p.write_text(json.dumps(dict(schema_version=3,id=sid,revision=1,cards=cards[i*6:i*6+6],tasks=tasks[i*6:i*6+6]),ensure_ascii=False,indent=2)+'\n')
  module['stages'].append(dict(id=sid,title=(['Rozszerzenie — zależności','Rozszerzenie — konfiguracja','Rozszerzenie — diagnostyka'] if ext else ['Podstawy','Zastosowanie','Scenariusze'])[i],description='Sześć zadań z teorią i wyjaśnieniem odpowiedzi.',difficulty=tasks[i*6]['difficulty'],order=order,pack_url='/'+path.replace('.yaml','.json'),pack_revision=1,task_count=6,pass_percent=80,requires=[] if order==1 else [f'encor.{key}.stage-{order-1}']))
 all_new.extend(tasks)


def Q(title,prompt,options,explain):
 q(title,prompt,options[0],[x+'|'+explain for x in options[1:]],explain,'Przeanalizuj warunki scenariusza; odpowiedź dotyczy wyłącznie podanych założeń.')
def C(title,prompt,template,values,explain):
 c(title,prompt,template,values,explain,'Zwróć uwagę na tryb konfiguracji i parametry wymienione w poleceniu.')
def save():
 assert len(all_new)==54,len(all_new)
 cat['revision']+=1
 (ROOT/'content/catalog.yaml').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n')
 print('Added',len(all_new),'ENCOR tasks')
MCAST='https://www.cisco.com/c/en/us/td/docs/routers/ios-xe/ip-multicast/ip-multicast/m_imc_basic_cfg-0.html'
SSM='https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipmulti_pim/configuration/15-s/imc-pim-15-s-book/imc_cfg_ssm.html'
WAN='https://www.cisco.com/c/en/us/td/docs/solutions/CVD/SDWAN/cisco-sdwan-design-guide.html'
WAND='https://www.cisco.com/c/en/us/support/docs/routers/sd-wan/222302-troubleshoot-common-sd-wan-control-and-d.html'
SDA='https://www.cisco.com/c/en/us/td/docs/solutions/CVD/Campus/cisco-sda-design-guide.html'
SDAV='https://www.cisco.com/c/en/us/td/docs/cloud-systems-management/network-automation-and-management/catalyst-center/cisco-validated-solution-profiles/validated-profile-manufacturing-sd-access.html'
start('multicast','Multicast — RPF, PIM, IGMP i SSM','3.3.d',[MCAST,SSM])
Q('Członkostwo hosta','Host IPv4 chce odbierać multicast w swoim LAN. Który protokół sygnalizuje lokalnemu routerowi zainteresowanie grupą?', ['IGMP','PIM pomiędzy hostem a routerem','MSDP pomiędzy hostem a switchem','BGP OPEN'],'IGMP dotyczy członkostwa odbiorców IPv4. PIM buduje drzewa multicast między routerami.')
Q('Rola PIM','Dlaczego PIM nazywa się Protocol Independent Multicast?', ['Może korzystać z informacji o osiągalności dostarczanych przez różne protokoły unicast','Nie potrzebuje informacji o drodze do źródła ani RP','Nie korzysta z adresów IP','Każda wersja PIM automatycznie szyfruje multicast'],'PIM nie wymaga jednego konkretnego IGP. Nadal potrzebuje informacji o routingu do kontroli RPF i budowania drzewa.')
Q('Drzewo współdzielone','Co oznacza wpis (*,G) w kontekście PIM-SM ASM?', ['Stan grupy G niezwiązany z jednym konkretnym źródłem','Trasę tylko do źródła o adresie 0.0.0.0','Wpis unicast do bramy domyślnej','Wyłącznie listę MAC odbiorców'],'G identyfikuje grupę. Gwiazdka oznacza dowolne źródło; w PIM-SM taki stan wiąże się z drzewem współdzielonym przez RP.')
Q('Kanał źródło–grupa','Co identyfikuje para (S,G)?', ['Konkretne źródło S i grupę G','Źródłowy oraz docelowy port TCP','Switch i jego bramę domyślną','Numer obszaru i router ID'],'Stan (S,G) pozwala rozróżniać strumienie różnych nadawców wysyłających do tej samej grupy.')
Q('Rendezvous Point','Jaka jest podstawowa rola RP w PIM-SM ASM?', ['Punkt spotkania informacji o źródłach i odbiorcach dla drzewa współdzielonego','Obowiązkowy serwer DHCP dla odbiorców','Jedyny router, przez który zawsze musi przechodzić każdy pakiet po przejściu na SPT','Urządzenie zamieniające multicast na DNS'],'RP jest istotny dla początkowego zestawienia komunikacji ASM. Po przejściu na drzewo źródłowe droga danych może omijać RP.')
Q('IGMPv3','Co wnosi IGMPv3 istotnego dla natywnego SSM?', ['Możliwość wskazania źródeł w zgłoszeniu członkostwa','Obowiązkowe uwierzytelnianie certyfikatem','Zastąpienie routingu multicast przez ARP','Automatyczne przydzielanie adresu źródłowego'],'Filtrowanie źródeł pozwala odbiorcy wskazać konkretny kanał (S,G). Sam IGMPv2 nie przekazuje takiej listy źródeł.')
Q('Kontrola RPF','Dla strumienia (S,G) router oczekuje pakietów na interfejsie wyznaczonym przez RPF do źródła S. Pakiet przychodzi innym interfejsem. Typowy skutek?', ['Odrzucenie z powodu niezgodności RPF','Przekazanie każdym portem bez kontroli','Automatyczne przestawienie wszystkich tras unicast','Zmiana grupy G na adres broadcast'],'RPF ogranicza pętle i duplikację. Kierunek nadejścia musi odpowiadać oczekiwanej ścieżce dla danego stanu multicast.')
Q('RPF w przykładzie','Załóż brak specjalnej tablicy RPF i statycznych mroute. Trasa do S=10.10.10.10 prowadzi przez Gi0/0. Pakiety (S,G) wpływają Gi0/1. Co sprawdzić?', ['Dlaczego routing do źródła wskazuje inny interfejs niż droga nadejścia multicast','Wyłącznie adres DNS odbiorcy','Wyłącznie lokalny priorytet STP odbiorcy','Czy grupa ma ten sam numer co VLAN'],'W tym scenariuszu wybór RPF opiera się na podanej trasie. Asymetria może powodować odrzucanie mimo poprawnego odbioru ramek na porcie.')
Q('SSM i RP','Dla natywnego SSM odbiorca zna źródło, a router obsługuje IGMPv3. Czy kanał SSM potrzebuje RP do odkrycia źródła?', ['Nie','Tak, zawsze','Tylko gdy źródło używa adresu prywatnego','Tylko gdy odbiorca jest w innym VLAN-ie'],'SSM buduje drzewo do wskazanego źródła. Nie potrzebuje mechanizmu odkrywania źródeł przez RP ani MSDP dla tego kanału.')
Q('Zakres SSM IPv4','Jaki jest standardowy zakres IPv4 SSM używany przez ip pim ssm default w IOS?', ['232.0.0.0/8','224.0.0.0/24','239.255.255.0/24','240.0.0.0/4'],'Standardowy zakres SSM to 232/8. Zakresy lokalnych grup sterujących mają inne zastosowanie.')
Q('IGMP a snooping','Co robi IGMP snooping na switchu L2?', ['Obserwuje komunikaty IGMP, by ograniczać rozsyłanie multicast do odpowiednich portów','Zastępuje PIM w routingu między podsieciami','Wyznacza RP przez BGP','Szyfruje pakiety grupowe'],'Snooping optymalizuje dystrybucję w LAN. Nie tworzy sam routingu multicast pomiędzy sieciami.')
Q('Przełączenie na SPT','W PIM-SM odbiorczy router przeszedł z drzewa współdzielonego na shortest-path tree do źródła. Co może się zmienić?', ['Droga danych może ominąć RP','Grupa multicast staje się adresem unicast','IGMP musi zostać wyłączone na odbiorcy','Cały ruch przechodzi obowiązkowo przez wszystkie RP'],'SPT jest drzewem do konkretnego źródła. Jego droga może różnić się od drogi przez RP.')
Q('Dwa źródła, jedna grupa','Odbiorca IGMPv3 INCLUDE chce tylko S1=192.0.2.10 dla G=232.1.1.1. S2=192.0.2.20 także nadaje do G. Co powinno określać subskrypcję SSM?', ['Para (192.0.2.10,232.1.1.1)','Sama grupa, bez rozróżnienia nadawcy','Każdy adres źródłowy w tej samej podsieci','Wyłącznie adres MAC najbliższego routera'],'W SSM grupę rozpatruje się razem ze źródłem. Wspólny adres G nie oznacza zgody na wszystkich nadawców.')
Q('Brak zainteresowanych interfejsów','Skrócony stan dydaktyczny:\n```text\n(192.0.2.10, 239.1.1.1)\n Incoming interface: GigabitEthernet0/0\n Outgoing interface list: Null\n```\nRPF jest poprawne. Dlaczego router może nie przekazywać strumienia dalej?', ['Nie ma aktywnego interfejsu wyjściowego dla tego stanu','Każda lista Null oznacza awarię fizyczną wejścia','Grupa 239.1.1.1 nigdy nie jest multicast','Router musi wysłać dane wszystkimi portami'],'Poprawne wejście nie wystarcza. Do replikacji potrzebne są właściwe stany i zainteresowanie odbiorców na wyjściach.')
Q('Rola MSDP','Do czego służą komunikaty Source-Active w MSDP w środowisku ASM?', ['Do wymiany informacji o aktywnych źródłach multicast między peerami, np. RP','Do transportu całego strumienia multicast jako tunel danych','Do rejestracji hosta jako odbiorcy IGMP','Do automatycznej zmiany wszystkich adresów grup'],'MSDP służy odkrywaniu źródeł w odpowiednich projektach ASM. Nie zastępuje zwykłej płaszczyzny przesyłania danych PIM.')
Q('Bidir-PIM','Które stwierdzenie opisuje bidirectional PIM?', ['Używa dwukierunkowego drzewa współdzielonego i mechanizmu designated forwarder','Buduje obowiązkowo osobny SPT dla każdego źródła','Wymaga IGMPv3 INCLUDE dla każdej grupy','Zamienia wszystkie źródła w serwery RP'],'Bidir-PIM jest zaprojektowany do ruchu wielu źródeł po drzewie współdzielonym. DF pomaga zapobiegać pętlom przy przekazywaniu w stronę RP.')
Q('IGMPv2 w sieci SSM','Aplikacja wymaga kanału (S,G), lecz host wysyła wyłącznie IGMPv2. Nie skonfigurowano SSM mapping ani mechanizmu zastępczego. Czego brakuje?', ['Przekazania routerowi żądanego źródła, np. przez IGMPv3','Wyłącznie większego MTU na porcie odbiorcy','Tylko zmiany source MAC hosta','Obowiązkowo dodatkowego RP dla SSM'],'IGMPv2 zgłasza grupę, ale nie źródło. Natywna subskrypcja SSM wymaga informacji o S, chyba że dostarcza ją jawny mechanizm mapowania.')
Q('RPF a odbiorca','W stanie drzewa źródłowego (S,G) operator sprawdza trasę unicast wyłącznie do odbiorcy. Dlaczego to nie wystarcza do oceny RPF?', ['RPF dla tego stanu odnosi się do źródła S, a nie adresu odbiorcy','RPF zawsze sprawdza tylko najbliższy serwer DNS','RPF nie korzysta z żadnego kierunku routingu','Adres odbiorcy musi być identyczny z grupą G'],'Dla wskazanego drzewa źródłowego analizuj drogę do S. Dla drzewa współdzielonego istotny jest kontekst drogi do RP.')
end()
start('sdwan','SD-WAN — płaszczyzny, OMP i jakość łączy','1.2',[WAN,WAND])
Q('Płaszczyzna zarządzania','Który komponent Cisco Catalyst SD-WAN odpowiada głównie za centralne zarządzanie i monitoring?', ['SD-WAN Manager, dawniej vManage','SD-WAN Validator, dawniej vBond','Wyłącznie WAN Edge','Każdy serwer DHCP w oddziale'],'Manager udostępnia zarządzanie, konfigurację i monitoring. Nie należy utożsamiać jego roli z przekazywaniem każdego pakietu użytkownika.')
Q('Płaszczyzna sterowania','Który komponent SD-WAN dystrybuuje informacje routingu overlay i polityki control plane?', ['SD-WAN Controller, dawniej vSmart','Manager jako obowiązkowy hop wszystkich pakietów','Serwer NTP operatora','Wyłącznie fizyczny modem transportowy'],'Controller realizuje funkcje sterowania overlay. WAN Edge pozostaje węzłem przesyłającym ruch użytkowników.')
Q('Rola Validator','Za co odpowiada SD-WAN Validator, dawniej vBond, podczas dołączania urządzeń?', ['Wspomaganie orkiestracji, uwierzytelnienia i odnalezienia komponentów sterujących','Stałe przekazywanie wszystkich danych klientów','Zastąpienie każdego next hop transportowego','Wymuszenie jednego operatora MPLS'],'Validator pomaga w początkowym zestawieniu overlay. Jego rola nie oznacza obowiązkowego tranzytu danych użytkowników.')
Q('Gdzie płyną dane','Które urządzenia realizują data plane overlay SD-WAN dla ruchu między oddziałami?', ['WAN Edge','Wyłącznie Manager','Wyłącznie Validator','Wyłącznie stacje administracyjne'],'Edge kończą transporty i tunele oraz przekazują ruch zgodnie z trasami i politykami. Kontroler nie musi być hopem danych.')
Q('Protokół OMP','Do czego służy Overlay Management Protocol w Cisco SD-WAN?', ['Do wymiany informacji overlay, m.in. tras i TLOC','Do zestawiania sąsiedztwa STP na każdym porcie','Do rozwiązywania nazw hostów','Do zastąpienia wszystkich protokołów LAN hosta'],'OMP działa w płaszczyźnie sterowania między odpowiednimi komponentami SD-WAN. Nie jest protokołem routingu hostów użytkowników.')
Q('Underlay SD-WAN','Co musi dostarczyć underlay, aby overlay mógł funkcjonować?', ['Osiągalność IP wymaganych końców i komponentów','Znajomość każdego prefiksu użytkownika overlay','Identical VLAN na wszystkich oddziałach','Jeden wspólny operator dla wszystkich łączy'],'Underlay transportuje pakiety pomiędzy końcami overlay. Sieć może korzystać z różnych rodzajów transportu i operatorów.')
Q('TLOC','Z jakich trzech elementów składa się klasyczny identyfikator TLOC?', ['System IP, color i encapsulation','VLAN, MAC i priorytet STP','Adres DNS, port HTTP i token API','Prefiks użytkownika, maska i numer ACL'],'TLOC opisuje lokalizację transportową WAN Edge. To nie tylko fizyczny adres IP interfejsu.')
Q('Znaczenie color','Co oznacza color transportu w SD-WAN?', ['Logiczną etykietę rodzaju/roli transportu używaną przez mechanizmy overlay i polityki','Kolor kabla światłowodowego','Szyfrowanie danych algorytmem o tej nazwie','Automatycznie gwarantowane SLA operatora'],'Color rozróżnia transporty logicznie. Sama nazwa biz-internet lub mpls nie dowodzi jakości, przepustowości ani bezpieczeństwa.')
Q('Monitorowanie tuneli','Jaka jest rola BFD w typowym data plane SD-WAN?', ['Weryfikacja żywotności ścieżek tunelowych i dostarczanie pomiarów jakości','Wyłącznie zapis konfiguracji w Managerze','Zastąpienie wszystkich certyfikatów','Przydzielanie adresów DHCP klientom'],'BFD pomaga ocenić dostępność i jakość ścieżek. Informacje te są używane m.in. w wyborze drogi według wymagań aplikacji.')
Q('Application-aware routing','Aplikacja głosowa ma wymagania dotyczące loss, latency i jitter. Czego potrzebuje application-aware routing?', ['Pomiarów jakości oraz polityki określającej dopuszczalne ścieżki i zachowanie','Tylko nazwy interfejsu zawierającej VOICE','Wyłącznie najwyższej prędkości nominalnej łącza','Wyłącznie adresu MAC telefonu'],'Wybór powinien uwzględniać rzeczywistą jakość względem kryteriów, nie tylko fakt, że interfejs jest up.')
Q('Łącze up, SLA niespełnione','Transport jest administracyjnie up i przenosi pakiety, lecz straty przekraczają próg polityki aplikacyjnej. Co jest możliwe?', ['Ścieżka może zostać uznana za niespełniającą SLA mimo osiągalności','Interfejs musi automatycznie przejść w shutdown','Każda aplikacja musi nadal bezwarunkowo używać tego łącza','OMP musi zmienić adres IP hostów'],'Dostępność i jakość to różne kryteria. Reakcja zależy od polityki i dostępności innych ścieżek.')
Q('Segmentacja VPN','Dwie usługi klientów mają odrębne service VPN w SD-WAN. Co jest zamierzonym efektem?', ['Oddzielne konteksty routingu i polityki segmentacji','Automatyczne połączenie obu RIB w jedną','Brak potrzeby tras do sieci klientów','Obowiązkowo różny operator dla każdego segmentu'],'Segmentacja pozwala odseparować usługi na wspólnej infrastrukturze. Wymiana tras między segmentami wymaga świadomego projektu.')
Q('Wybór ścieżki według progów','Załóż warunek polityki: loss ≤ 1%, latency ≤ 100 ms, jitter ≤ 20 ms.\n\n| Ścieżka | Loss | Latency | Jitter |\n|---|---:|---:|---:|\n| A | 0,2% | 60 ms | 8 ms |\n| B | 2% | 25 ms | 4 ms |\n\nKtóra spełnia wszystkie warunki?', ['Tylko A','Tylko B','Obie','Żadna'],'B ma mniejsze opóźnienie, ale przekracza próg strat. Przy podanej koniunkcji wymagań spełnia je wyłącznie A.')
Q('Brak ścieżki zgodnej z SLA','Oba transporty przekroczyły progi aplikacji. Czy można bez znajomości konfiguracji stwierdzić, że ruch będzie zawsze odrzucony?', ['Nie; zachowanie zależy m.in. od polityki fallback i trybu egzekwowania','Tak, każdy wariant SD-WAN zawsze odrzuca','Tak, ponieważ BFD zawsze usuwa adresy IP','Nie, bo progi SLA nigdy nie wpływają na ruch'],'Trzeba sprawdzić konfigurację reakcji przy braku zgodnej ścieżki. Nie zakładaj jednego zachowania dla wszystkich polityk.')
Q('Control up, data down','Skrócony stan dydaktyczny: połączenia do Controller są up, lecz BFD do zdalnego Edge jest down. Co należy rozdzielić w diagnozie?', ['Osiągalność control plane od drogi tunelu danych między Edge','Uznać, że działający Controller dowodzi działania wszystkich tuneli','Sprawdzać wyłącznie GUI Managera','Wyłączyć wszystkie polityki bez analizy transportu'],'Control connections i data tunnels mają różne końce oraz warunki dostępności. Sprawdź transport, filtrowanie, NAT i parametry tunelu.')
Q('Manager chwilowo niedostępny','Manager jest niedostępny, a Edge mają działające tunele, zachowane trasy i połączenia sterujące. Co jest trafnym wnioskiem?', ['Sama awaria Managera nie dowodzi natychmiastowego zatrzymania istniejącego forwarding','Wszystkie pakiety muszą zniknąć, bo zawsze przechodzą przez GUI','Edge automatycznie usuwa każdy interfejs','Overlay staje się nieszyfrowany z definicji'],'Zarządzanie i forwarding są rozdzielone. Możliwość dalszego ruchu nie oznacza braku wpływu na monitoring i zmiany konfiguracji.')
Q('Certyfikaty i czas','Nowy Edge ma osiągalność IP, ale nie przechodzi uwierzytelnienia komponentów. Co jest uzasadnionym sprawdzeniem?', ['Tożsamość urządzenia, certyfikaty, organizację oraz czas systemowy','Wyłącznie nazwę VLAN hosta użytkownika','Wyłącznie zmianę metryki OSPF w każdej lokalizacji','Założenie, że ping gwarantuje autoryzację'],'Osiągalność IP nie dowodzi zgodności tożsamości. Weryfikacja certyfikatów i danych organizacji jest oddzielnym etapem dołączania.')
Q('Dwa łącza, wspólna awaria','Oddział ma dwóch operatorów, lecz oba kable biegną tą samą kanalizacją. Co nadal ogranicza odporność?', ['Wspólny fizyczny punkt awarii mimo dwóch transportów logicznych','Brak trzeciego koloru w nazwie interfejsu','Sam fakt zastosowania OMP','Niemożność segmentacji na Edge'],'Redundancję ocenia się także pod kątem wspólnych zależności: trasy kablowej, zasilania, urządzeń i punktów wejścia do budynku.')
end()
start('sdaccess','SD-Access — fabric, segmentacja i dostęp zewnętrzny','1.3',[SDA,SDAV])
Q('Płaszczyzna sterowania fabric','Na jakiej technologii bazuje control plane Cisco SD-Access?', ['LISP','STP jako baza endpointów','MSDP','NETCONF jako protokół transportu każdego pakietu'],'LISP zapewnia mapowanie identyfikatorów endpointów na ich lokalizację w fabric. To inna rola niż zarządzanie konfiguracją.')
Q('Płaszczyzna danych fabric','Która technologia jest podstawą enkapsulacji data plane SD-Access?', ['VXLAN','Zwykły trunk 802.1Q przez cały rdzeń bez overlay','SMTP','SSH jako tunel wszystkich pakietów użytkownika'],'VXLAN przenosi ruch overlay przez underlay IP. Nie należy mylić go z LISP control plane.')
Q('Płaszczyzna polityk','Jaka technologia stanowi podstawę policy plane SD-Access?', ['Cisco TrustSec i grupowanie bezpieczeństwa','Wyłącznie OSPF area range','Wyłącznie wybór root bridge','Wyłącznie mapowanie DNS'],'TrustSec umożliwia polityki oparte na grupach bezpieczeństwa. Segmentacja nie musi opierać się tylko na adresach IP.')
Q('Zarządzanie fabric','Który system służy do centralnego projektowania, automatyzacji i assurance SD-Access?', ['Cisco Catalyst Center','Wyłącznie SD-WAN Validator','Dowolny serwer IGMP','Wyłącznie lokalny agent SNMP hosta'],'Catalyst Center realizuje funkcje zarządzania i automatyzacji fabric; nie jest obowiązkowym hopem pakietów użytkownika.')
Q('Fabric edge','Jaką rolę pełni fabric edge node?', ['Łączy endpointy z fabric i realizuje funkcje brzegowe overlay','Wyłącznie przechowuje kopię konfiguracji Catalyst Center','Zawsze jest tylko transparentnym repeaterem','Wyłącznie rozgłasza certyfikaty WAN'],'Edge jest punktem dostępu endpointów do fabric. Rejestruje ich lokalizację i uczestniczy w obsłudze ruchu oraz polityk.')
Q('Fabric border','Który węzeł łączy fabric z sieciami zewnętrznymi?', ['Fabric border node','Wyłącznie intermediate node bez roli border','Każdy serwer końcowy','Wyłącznie kontroler WLAN niezależnie od projektu'],'Border zapewnia granicę między fabric i sieciami spoza niej. Sposób połączenia zależy od projektu i rodzaju zewnętrznych sieci.')
Q('Control plane node','Jaką funkcję LISP pełni typowy SD-Access control plane node?', ['Map-Server i Map-Resolver','Wyłącznie DHCP relay','Wyłącznie translator NAT portów','Wyłącznie odbiornik SPAN'],'Control plane utrzymuje i udostępnia informacje o lokalizacji endpointów. Nie musi przekazywać całego ruchu danych.')
Q('Intermediate node','Jakie jest podstawowe zadanie intermediate node w underlay SD-Access?', ['Zapewnienie tranzytowej osiągalności IP pomiędzy węzłami fabric','Przechowywanie polityk SGACL dla każdego endpointu jako obowiązkowa rola','Kończenie każdego tunelu VXLAN','Uwierzytelnianie wszystkich użytkowników 802.1X'],'Węzeł pośredni przenosi pakiety underlay. Nie musi pełnić funkcji edge, border ani map-servera.')
Q('Makrosegmentacja','Czemu służą Virtual Networks w SD-Access?', ['Oddzielaniu logicznych domen routingu, np. grup użytkowników o różnych wymaganiach','Wyłącznie zmianie kolorów mapy GUI','Łączeniu wszystkich usług w jeden broadcast domain','Wyłącznie nadawaniu priorytetów STP'],'VN zapewniają makrosegmentację. Dalsze ograniczenia wewnątrz segmentu mogą opierać się na grupach bezpieczeństwa.')
Q('Mikrosegmentacja','Dwa urządzenia należą do tej samej VN, ale polityka ma rozróżnić grupę FINANCE i GUEST. Co pasuje do tego celu?', ['SGT i polityka między grupami, np. SGACL','Wyłącznie zmiana OSPF router ID','Wyłącznie zwiększenie MTU','Wyłącznie zmiana nazwy interfejsu'],'Grupy bezpieczeństwa umożliwiają bardziej szczegółową politykę wewnątrz VN. Sama wspólna VN nie oznacza pełnej zgody na komunikację.')
Q('Rola ISE','Jaka jest typowa rola Cisco ISE w projekcie SD-Access?', ['Tożsamość, uwierzytelnianie i klasyfikacja do polityk/grup bezpieczeństwa','Przekazywanie każdego pakietu VXLAN jako router transit','Zastąpienie wszystkich tras underlay','Pełnienie roli każdego serwera aplikacyjnego'],'ISE wspiera dostęp i polityki oparte na tożsamości. Nie jest wymaganym hopem zwykłego ruchu danych endpointów.')
Q('Anycast gateway','Jaką korzyść daje rozproszona anycast gateway dla podsieci w fabric?', ['Lokalną obsługę bramy przy zachowaniu spójnej tożsamości bramy w odpowiednich węzłach','Brak potrzeby jakiegokolwiek routingu','Wymóg wysyłania każdego pakietu przez Catalyst Center','Zamianę wszystkich hostów w routery'],'Rozproszona brama wspiera lokalne wejście do routingu i mobilność endpointów. Wymaga spójnej konfiguracji fabric.')
Q('Ruch wewnętrzny działa, zewnętrzny nie','Endpointy komunikują się wewnątrz VN, ale nie z serwerem poza fabric. Który obszar sprawdzić jako kolejny?', ['Border, routing zewnętrzny, drogę powrotną i polityki','Wyłącznie wymianę kabli wszystkich edge','Wyłącznie nazwę profilu GUI','Uznać pełną awarię LISP mimo działającego ruchu wewnątrz'],'Działanie wewnątrz nie potwierdza granicy zewnętrznej. Diagnozuj dalszą ścieżkę i powrót, zachowując kontekst VN.')
Q('Małe pakiety działają','Duże pakiety między edge zawodzą, małe przechodzą. Podczas migracji zachowano zbyt małe MTU na części underlay. Dlaczego to istotne?', ['Enkapsulacja VXLAN zwiększa rozmiar transportowanego pakietu','LISP automatycznie kompresuje każdy pakiet do MTU','SGT zawsze usuwa nagłówek IP','Anycast gateway gwarantuje nieograniczone MTU'],'Underlay musi uwzględniać narzut overlay. Sama osiągalność pingiem o małym rozmiarze nie weryfikuje pełnej ścieżki MTU.')
Q('Przeniesienie endpointu','Endpoint przechodzi z jednego edge na drugi w obrębie poprawnie skonfigurowanego fabric. Co musi odpowiadać nowej lokalizacji?', ['Mapowanie endpointu na właściwy locator/edge','Wymiana wszystkich switchy intermediate','Zmiana wszystkich VN na wspólny VLAN','Wyłączenie rozproszonej bramy'],'Control plane musi odzwierciedlać lokalizację endpointu, aby zdalne węzły kierowały ruch do aktualnego miejsca przyłączenia.')
Q('SGT nie jest szyfrowaniem','Pakiety mają przypisaną grupę bezpieczeństwa SGT. Czy sama etykieta zapewnia poufność payloadu?', ['Nie; identyfikuje grupę dla polityki, nie szyfruje danych','Tak, każda SGT jest kluczem AES','Tak, jeśli numer SGT przekracza 100','Tak, jeśli endpoint jest w tej samej VN'],'Etykietowanie i egzekwowanie dostępu to inne funkcje niż szyfrowanie. Poufność wymaga odpowiednich mechanizmów projektu.')
Q('Integracja z tradycyjną siecią','Firma wdraża SD-Access częściowo, zachowując tradycyjną sieć kampusową. Co trzeba jawnie zaprojektować?', ['Połączenie graniczne, routing i zachowanie segmentacji/polityk między domenami','Założyć, że wszystkie VLAN-y automatycznie stają się VN','Założyć, że Catalyst Center przeniesie każdą politykę bez mapowania','Wyłącznie zmienić nazwy switchy'],'Fabric nie usuwa potrzeby projektu styku z istniejącą infrastrukturą. Trzeba określić zasięg sieci i polityk na granicy.')
Q('Łączenie ról','Czy role edge, border i control plane muszą zawsze znajdować się na trzech osobnych fizycznych urządzeniach?', ['Nie; wspierane projekty mogą łączyć role, z uwzględnieniem platformy i skali','Tak, bez wyjątków','Nie, bo control plane zawsze działa na każdym hoście','Tak, ponieważ VXLAN nie obsługuje routingu'],'Role logiczne nie narzucają zawsze osobnych urządzeń. Projekty typu fabric-in-a-box wymagają sprawdzenia wsparcia, skali i odporności.')
end()
save()
